//! C API. The header `include/rperfetto_sdk.h` is generated by cbindgen
//! (`scripts/gen_header.sh`).
//!
//! Conventions: strings are NUL-terminated UTF-8 (invalid UTF-8 is replaced);
//! a `track` of 0 means "the calling thread's track"; categories are handles
//! returned by `rpf_category_register`.
#![allow(clippy::missing_safety_doc)]

use crate::{
    Arg, ArgValue, Backends, Category, CategoryFilter, CounterTrack, InitArgs, SessionConfig, Track, TracingSession,
};
use std::borrow::Cow;
use std::ffi::{c_char, CStr};
use std::sync::Mutex;

pub const RPF_BACKEND_IN_PROCESS: u32 = 1;
pub const RPF_BACKEND_SYSTEM: u32 = 2;
pub const RPF_BACKEND_ATRACE: u32 = 4;

/// Initialization arguments. Zero-initialize and fill what you need.
#[repr(C)]
pub struct RpfInitArgs {
    /// Bitwise OR of RPF_BACKEND_*.
    pub backends: u32,
    /// Optional process name (NULL = autodetect).
    pub process_name: *const c_char,
    /// System backend: producer name (NULL = process name).
    pub producer_name: *const c_char,
    /// System backend: producer socket path (NULL = platform default).
    pub producer_socket: *const c_char,
    /// System backend: shared memory size hint in KiB (0 = 1024).
    pub shmem_size_hint_kb: u32,
    /// System backend: fail instead of connecting in the background when
    /// traced is not running.
    pub no_retry_connect: bool,
    /// ATRACE backend: trace_marker path (NULL = autodetect).
    pub atrace_marker_path: *const c_char,
}

#[repr(C)]
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum RpfArgType {
    Bool = 0,
    Int = 1,
    Uint = 2,
    Double = 3,
    String = 4,
    Pointer = 5,
}

#[repr(C)]
#[derive(Clone, Copy)]
pub union RpfArgValue {
    pub b: bool,
    pub i: i64,
    pub u: u64,
    pub d: f64,
    pub s: *const c_char,
    pub p: *const std::ffi::c_void,
}

/// A debug annotation (event argument).
#[repr(C)]
#[derive(Clone, Copy)]
pub struct RpfArg {
    pub name: *const c_char,
    pub kind: RpfArgType,
    pub value: RpfArgValue,
}

/// In-process session configuration. Zero-initialize for defaults.
#[repr(C)]
pub struct RpfSessionConfig {
    /// Buffer size in KiB (0 = 32 MiB).
    pub buffer_size_kb: u32,
    /// true: ring buffer (drop oldest); false: stop when full.
    pub ring_buffer: bool,
    /// Category filter, Perfetto TrackEventConfig semantics. May be NULL.
    pub enabled_categories: *const *const c_char,
    pub num_enabled_categories: usize,
    pub disabled_categories: *const *const c_char,
    pub num_disabled_categories: usize,
}

/// Opaque in-process session.
pub struct RpfSession {
    inner: Mutex<TracingSession>,
}

/// Opaque category handle.
pub type RpfCategory = *const Category;

unsafe fn cstr<'a>(p: *const c_char) -> Option<Cow<'a, str>> {
    (!p.is_null()).then(|| CStr::from_ptr(p).to_string_lossy())
}

unsafe fn str_list(p: *const *const c_char, n: usize) -> Vec<String> {
    if p.is_null() {
        return Vec::new();
    }
    (0..n).filter_map(|i| cstr(*p.add(i)).map(|s| s.into_owned())).collect()
}

/// Initializes the selected backends. Returns false on failure.
#[no_mangle]
pub unsafe extern "C" fn rpf_init(args: *const RpfInitArgs) -> bool {
    let mut ia = InitArgs::default();
    if let Some(a) = args.as_ref() {
        ia.backends = Backends(a.backends);
        ia.process_name = cstr(a.process_name).map(|s| s.into_owned());
        if let Some(p) = cstr(a.producer_name) {
            ia.producer_name = p.into_owned();
        }
        ia.producer_socket = cstr(a.producer_socket).map(|s| s.into_owned());
        if a.shmem_size_hint_kb != 0 {
            ia.shmem_size_hint_kb = a.shmem_size_hint_kb;
        }
        ia.retry_connect = !a.no_retry_connect;
        ia.atrace_marker_path = cstr(a.atrace_marker_path).map(|s| s.into_owned());
    }
    crate::init(ia).is_ok()
}

/// Flushes and tears down all backends.
#[no_mangle]
pub extern "C" fn rpf_shutdown() {
    crate::shutdown();
}

/// Bitmask of initialized backends.
#[no_mangle]
pub extern "C" fn rpf_initialized_backends() -> u32 {
    crate::initialized_backends().0
}

/// True while traced has the track_event data source started (system backend).
#[no_mangle]
pub extern "C" fn rpf_system_is_tracing() -> bool {
    #[cfg(any(target_os = "linux", target_os = "android"))]
    return crate::system::is_tracing();
    #[cfg(not(any(target_os = "linux", target_os = "android")))]
    false
}

/// Returns the category with this name (created on first call). The handle
/// stays valid for the life of the process.
#[no_mangle]
pub unsafe extern "C" fn rpf_category_register(name: *const c_char) -> RpfCategory {
    match cstr(name) {
        Some(n) => Category::dynamic(&n) as *const Category,
        None => std::ptr::null(),
    }
}

/// Application-level switch for a category (default on).
#[no_mangle]
pub unsafe extern "C" fn rpf_category_set_enabled(cat: RpfCategory, enabled: bool) {
    if let Some(c) = cat.as_ref() {
        // SAFETY: handles come from rpf_category_register (leaked, 'static).
        let c: &'static Category = &*(c as *const Category);
        c.set_enabled(enabled);
    }
}

/// True if any active backend records this category right now.
#[no_mangle]
pub unsafe extern "C" fn rpf_category_is_enabled(cat: RpfCategory) -> bool {
    match cat.as_ref() {
        Some(c) => (&*(c as *const Category)).is_enabled(),
        None => false,
    }
}

unsafe fn cat_ref(cat: RpfCategory) -> Option<&'static Category> {
    cat.as_ref().map(|c| &*(c as *const Category))
}

/// The calling thread's track.
#[no_mangle]
pub extern "C" fn rpf_track_thread() -> u64 {
    Track::current_thread().uuid()
}

/// The process track.
#[no_mangle]
pub extern "C" fn rpf_track_process() -> u64 {
    Track::process().uuid()
}

/// A named track; `parent` 0 = the process track.
#[no_mangle]
pub unsafe extern "C" fn rpf_track_named(name: *const c_char, parent: u64) -> u64 {
    let name = cstr(name).unwrap_or_default();
    let parent = if parent == 0 { Track::process() } else { Track::from_uuid(parent).unwrap_or_else(Track::process) };
    Track::named_with_parent(&name, parent).uuid()
}

/// A counter track; `parent` 0 = the process track; `unit` may be NULL.
#[no_mangle]
pub unsafe extern "C" fn rpf_track_counter(name: *const c_char, parent: u64, unit: *const c_char) -> u64 {
    let name = cstr(name).unwrap_or_default();
    let unit = cstr(unit);
    let parent = if parent == 0 { Track::process() } else { Track::from_uuid(parent).unwrap_or_else(Track::process) };
    CounterTrack::with_parent(&name, parent, unit.as_deref()).uuid()
}

/// Names the calling thread in the trace.
#[no_mangle]
pub unsafe extern "C" fn rpf_set_thread_name(name: *const c_char) {
    if let Some(n) = cstr(name) {
        crate::set_thread_name(&n);
    }
}

unsafe fn with_args<R>(args: *const RpfArg, n: usize, f: impl FnOnce(&[Arg]) -> R) -> R {
    if args.is_null() || n == 0 {
        return f(&[]);
    }
    let raw = std::slice::from_raw_parts(args, n);
    let names: Vec<Cow<str>> = raw.iter().map(|a| cstr(a.name).unwrap_or_default()).collect();
    let strs: Vec<Cow<str>> = raw
        .iter()
        .map(|a| if a.kind == RpfArgType::String { cstr(a.value.s).unwrap_or_default() } else { Cow::Borrowed("") })
        .collect();
    let v: Vec<Arg> = raw
        .iter()
        .enumerate()
        .map(|(i, a)| Arg {
            name: &names[i],
            value: match a.kind {
                RpfArgType::Bool => ArgValue::Bool(a.value.b),
                RpfArgType::Int => ArgValue::Int(a.value.i),
                RpfArgType::Uint => ArgValue::UInt(a.value.u),
                RpfArgType::Double => ArgValue::Double(a.value.d),
                RpfArgType::String => ArgValue::Str(&strs[i]),
                RpfArgType::Pointer => ArgValue::Pointer(a.value.p as usize as u64),
            },
        })
        .collect();
    f(&v)
}

fn track_of(t: u64) -> Option<Track> {
    (t != 0).then_some(Track { uuid: t })
}

/// Begins a slice. `track` 0 = calling thread. `args` may be NULL.
#[no_mangle]
pub unsafe extern "C" fn rpf_slice_begin(cat: RpfCategory, track: u64, name: *const c_char, args: *const RpfArg, num_args: usize) {
    let Some(c) = cat_ref(cat) else { return };
    if !c.is_enabled() {
        return;
    }
    let name = cstr(name).unwrap_or_default();
    with_args(args, num_args, |a| match track_of(track) {
        Some(t) => crate::slice_begin_on(c, t, &name, a),
        None => crate::slice_begin(c, &name, a),
    });
}

/// Ends the innermost slice on `track` (0 = calling thread).
#[no_mangle]
pub unsafe extern "C" fn rpf_slice_end(cat: RpfCategory, track: u64) {
    let Some(c) = cat_ref(cat) else { return };
    match track_of(track) {
        Some(t) => crate::slice_end_on(c, t),
        None => crate::slice_end(c),
    }
}

/// Instant event on `track` (0 = calling thread).
#[no_mangle]
pub unsafe extern "C" fn rpf_instant(cat: RpfCategory, track: u64, name: *const c_char, args: *const RpfArg, num_args: usize) {
    let Some(c) = cat_ref(cat) else { return };
    if !c.is_enabled() {
        return;
    }
    let name = cstr(name).unwrap_or_default();
    with_args(args, num_args, |a| match track_of(track) {
        Some(t) => crate::instant_on(c, t, &name, a),
        None => crate::instant(c, &name, a),
    });
}

/// Integer counter sample on a track from rpf_track_counter.
#[no_mangle]
pub unsafe extern "C" fn rpf_counter_i64(cat: RpfCategory, counter_track: u64, value: i64) {
    if let Some(c) = cat_ref(cat) {
        crate::counter(c, CounterTrack { uuid: counter_track }, value);
    }
}

/// Floating-point counter sample on a track from rpf_track_counter.
#[no_mangle]
pub unsafe extern "C" fn rpf_counter_f64(cat: RpfCategory, counter_track: u64, value: f64) {
    if let Some(c) = cat_ref(cat) {
        crate::counter(c, CounterTrack { uuid: counter_track }, value);
    }
}

/// Pushes the calling thread's buffered events to the backends.
#[no_mangle]
pub extern "C" fn rpf_flush_current_thread() {
    crate::flush_current_thread();
}

/// Starts an in-process session (requires RPF_BACKEND_IN_PROCESS). `cfg` may
/// be NULL. Returns NULL on failure (e.g. a session is already running).
#[no_mangle]
pub unsafe extern "C" fn rpf_session_start(cfg: *const RpfSessionConfig) -> *mut RpfSession {
    let mut sc = SessionConfig::default();
    if let Some(c) = cfg.as_ref() {
        if c.buffer_size_kb != 0 {
            sc.buffer_size_kb = c.buffer_size_kb;
        }
        sc.ring_buffer = c.ring_buffer;
        sc.categories = CategoryFilter {
            enabled: str_list(c.enabled_categories, c.num_enabled_categories),
            disabled: str_list(c.disabled_categories, c.num_disabled_categories),
        };
    }
    match TracingSession::start(sc) {
        Ok(s) => Box::into_raw(Box::new(RpfSession { inner: Mutex::new(s) })),
        Err(_) => std::ptr::null_mut(),
    }
}

/// Moves all threads' buffered events into the session buffer.
#[no_mangle]
pub unsafe extern "C" fn rpf_session_flush(s: *mut RpfSession) {
    if let Some(s) = s.as_ref() {
        s.inner.lock().unwrap().flush();
    }
}

/// Stops recording (the data stays available for rpf_session_write_file).
#[no_mangle]
pub unsafe extern "C" fn rpf_session_stop(s: *mut RpfSession) {
    if let Some(s) = s.as_ref() {
        s.inner.lock().unwrap().stop();
    }
}

/// Writes the trace (a snapshot if still running) to `path`.
#[no_mangle]
pub unsafe extern "C" fn rpf_session_write_file(s: *mut RpfSession, path: *const c_char) -> bool {
    let (Some(s), Some(p)) = (s.as_ref(), cstr(path)) else { return false };
    s.inner.lock().unwrap().write_to_file(&*p).is_ok()
}

/// Copies the trace into a library-allocated buffer. Returns
/// its size; `*out` must be released with rpf_buffer_free.
#[no_mangle]
pub unsafe extern "C" fn rpf_session_read(s: *mut RpfSession, out: *mut *mut u8) -> usize {
    let Some(s) = s.as_ref() else { return 0 };
    let data = s.inner.lock().unwrap().trace_bytes().into_boxed_slice();
    let len = data.len();
    if !out.is_null() {
        *out = Box::into_raw(data) as *mut u8;
    }
    len
}

#[no_mangle]
pub unsafe extern "C" fn rpf_buffer_free(buf: *mut u8, len: usize) {
    if !buf.is_null() {
        drop(Box::from_raw(std::ptr::slice_from_raw_parts_mut(buf, len)));
    }
}

/// Stops (if needed) and frees the session.
#[no_mangle]
pub unsafe extern "C" fn rpf_session_destroy(s: *mut RpfSession) {
    if !s.is_null() {
        drop(Box::from_raw(s));
    }
}
